        if (Math.random() < dt*2.2) parts.push({ k:'dust', x: m.x + rand(-10, 10), y: m.y, vx: rand(-8, 8), vy: rand(-14, -6), g: 0, life: rand(.8, 1.4), t: 0, r: rand(4, 8) });
