  r.ptT = (r.ptT || 0) - dt;
  if (r.ptT <= 0 || !r.pt){ r.ptT = rand(2.2, 3.8); const s = FIRE_SITE[Math.floor(Math.random()*4)]; r.pt = { x: FIRE_T.x + s[0]*FIRE_T.r, y: FIRE_T.y + s[1]*FIRE_T.r*0.9 }; if (r.st === 'study' && Math.random() < 0.5) robotSays(r, 'hmm'); }
