  const turn = (a, sd) => { const c = Math.cos(a*sd), s = Math.sin(a*sd); return { x: ux*c - uy*s, y: ux*s + uy*c }; };
  const sides = l.skirt ? [l.skirt, -l.skirt] : [1, -1];
