  L.sort((a, b) => Math.hypot(a.f.x - h.x, a.f.y - h.y) - Math.hypot(b.f.x - h.x, b.f.y - h.y));
  const i = L[0].i; FLOWERS[i].full = false; FLOWERS[i].t = 0;
