  const last = h.slabLast, taken = i => HB.some(q => q !== h && q.st === 'snipLab' && q.slab === i);
  let c = FLOWERS.map((f, i) => ({ f, i })).filter(o => flowerOn(o.f) && !taken(o.i) && Math.hypot(o.f.x - HIVE.x, (o.f.y - HIVE.y)*1.3) < 330);
  if (!c.length) return -1;
