          const hy = fl.y - flowerHead(fl);
          sparkle(fl.x, hy); for (let k=0;k<10;k++) parts.push({ k:'star', x: fl.x + rand(-6, 6), y: hy + rand(-6, 4), vx: rand(-40, 40), vy: rand(-55, -15), g: 40, life: rand(.5, .9), t: 0 });
          const a = sndAt(fl.x, fl.y); sfx('chime', 'sale');
