    g.setTransform(G.rs*G.z, 0, 0, G.rs*G.z, G.rs*(G.ox + G.mx), G.rs*(G.oy + G.my)); g.globalAlpha = 1;
    g.drawImage(tc, a.x0, a.y0, a.nx*ANT_CELL, a.ny*ANT_CELL);
