  c.strokeStyle = '#5f6e33'; c.lineWidth = 0.9; c.lineCap = 'round'; for (const [gx, gl, gd] of [[-3, 6, -1.5], [-1.6, 8, -0.4], [2.6, 7, 1.4], [3.8, 5, 2.4]]){ c.beginPath(); c.moveTo(gx, 0); c.quadraticCurveTo(gx + gd*0.3, -gl*0.6, gx + gd, -gl); c.stroke(); }
