  c.fillStyle = '#c99434'; ell(c, 1.1, -0.6, 1.1, 0.7); c.fill();
  c.fillStyle = '#2a1e14'; ell(c, 3, 0.35, 1.1, 1.05); c.fill();
  c.fillStyle = 'rgba(255,255,255,.45)'; ell(c, 3.2, -0.1, 0.35, 0.3); c.fill();
