    c.fillStyle = '#2f2a26'; c.fillRect(-bw/2, by, bw, bH);
    c.fillStyle = '#f2c230'; for (let x = -bw/2 - 8; x < bw/2 + 8; x += 7){ c.beginPath(); c.moveTo(x, by + bH); c.lineTo(x + 3.5, by + bH); c.lineTo(x + 9.5, by); c.lineTo(x + 6, by); c.closePath(); c.fill(); }
    c.restore();
