  c.fillStyle = 'rgba(35,28,12,.3)'; ell(c, 0, 1, bw*0.85*(1 - (h.jz || 0)*0.03), 4.5); c.fill();
  if (slab && h.jz) c.translate(0, -h.jz);   // V35: a little hop
