  { const T = truck, on = T.st === 'arrive' || T.st === 'leave';
    if (T.st !== 'away'){ for (const k of [0, 1]){ const w = T._w || (T._w = [{ face: -1 }, { face: -1 }]); const o = w[k]; o.x = T.x + (k ? 44 : -52); o.y = LANE + 4; o.face = T.x > (o.px || T.x) ? 1 : -1; o.px = T.x; wade(o, on, 9, dt, 1.8); } } }
