    const q = Math.round(t.a*(1 - t.t/9)*N); if (q <= 0) continue;
    const P = paths[q] || (paths[q] = new Path2D());
    for (const x of [t.x - t.h, t.x + t.h]){ P.moveTo(x + 3, t.y + 0.5); P.ellipse(x, t.y + 0.5, 3, 1.3, 0, 0, TAU); }
