  for (const h of HB) if (h.st !== 'gone' && h.st !== 'ride' && xs(h.x, 30) && rch(h.y, h.st === 'brolly' ? 95 : 60)) out.push({ y: h.y, f: () => h.kind === 'blower' ? drawBlower(h) : drawShaker(h) });
