  c.fillStyle = 'rgba(30,20,10,.25)'; ell(c, 0.8, 1.2, 9.6, 9.2); c.fill();
  c.fillStyle = sh; ell(c, 0, 0, 9.4, 9); c.fill();
  c.strokeStyle = '#6e624c'; c.lineWidth = 0.7; ell(c, 0, 0, 9.4, 9); c.stroke();
  // the band turns with it
