    const i = cardOpen.i, st = k === 'robot' ? styleOf(i) : helperStyleOf(k, i);
    title = navTitle(k, i, st.name); live = k === 'robot' ? 'robot' : 'helper'; head = 'portrait';
    const tp = tasksPanel(k, i);
