    '<path d="M-6.6,0 Q0,-6.2 6.6,0 Q0,6.2 -6.6,0Z" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"/><circle r="2.5" fill="currentColor"/><circle cx="-.8" cy="-.9" r=".8" fill="#fbf3e2"/></svg></button>';
