  const top = cb.getBoundingClientRect().top;
  const k = { who: cardOpen.kind + '|' + cardTab, st: cb.scrollTop, picks: [...card.querySelectorAll('.pick')].map(p => p.scrollTop) };
  // the thing just tapped (a buy, Assign, a picker option) stays put
